// примерно так await обходится с продолжением
var ctx = SynchronizationContext.Current;   // 1. захват в момент приостановки
// … задача завершилась на потоке пула …
if (ctx != null)
    ctx.Post(_ => MoveNext(), null);         // 2a. в очередь UI-потока
else
    MoveNext();                              // 2b. прямо здесь, в пуле

